// === Tab: mySketch ===
let p = new Array(2000);
let diagonal;


function setup() {
  for (i = 0; i<p.length; i++) {
    p[i] = new Particle();

  }
  createCanvas(1440, 900);
  diagonal = int(sqrt)(width*width + height * height)/2;
  background(10,10,0);
  noStroke();

  frameRate(30);
}
let rotation = 0;
function draw() {
  if (!mousePressed)  {
    background(10,0,40);
  }

  translate(width/2, height/2);
  rotation-=0.002;
  rotate(rotation);

  for (i = 0; i<p.length; i++) {
    p[i].draw();
    if (p[i].drawDist()>diagonal) {
      p[i] = new Particle();
    }
  }
}

class Particle {
  n;
  r;
  o;
  l;
  constructor() {
    l = 1;
    n = random(1, width/2);
    r = random(0, TWO_PI);
    o = random(1, random(1, width/n));
  }

  function draw() {
    l++;
    pushMatrix();
    rotate(r);
    translate(drawDist(), 0);
    fill(255, min(l, 255));
    ellipse(0, 0, width/o/50, width/o/50);
    popMatrix();

    o-=0.07;
  }
  drawDist() {
    return atan(n/o)*width/HALF_PI;
  }
}

